class Solution:
    def areAlmostEqual(self, s1: str, s2: str) -> bool:
        diff = []
        for a, b in zip(s1, s2):
            if a == b:
                continue
            if len(diff) == 2:
                return False
            diff.append([a, b] if not diff else [b, a])
        return not diff or (len(diff) == 2 and diff[0] == diff[1])

